<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import type { Idea, Product } from '../types'
import IdeaCard from '../components/IdeaCard.vue'
import { statusLabels } from '../utils'
const route = useRoute(); const router = useRouter(); const query = ref(''); const ideas = ref<Idea[]>([]); const products = ref<Product[]>([]); const searched = ref(false); const loading = ref(false); const error = ref('')
async function search() { if (!query.value.trim()) return; loading.value = true; error.value = ''; router.replace({ query: { q: query.value } }); try { const result = await api<{ ideas: Idea[]; products: Product[] }>(`/search?q=${encodeURIComponent(query.value.trim())}`); ideas.value = result.ideas; products.value = result.products; searched.value = true } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
onMounted(() => { if (typeof route.query.q === 'string') { query.value = route.query.q; search() } })
</script>
<template><section><div class="page-heading"><div><h1>全局搜索</h1><p>搜索原始文字、标题、名称、摘要、标签、分类、动态属性和商品描述。</p></div></div><form class="toolbar" @submit.prevent="search"><input v-model="query" type="search" maxlength="200" autofocus placeholder="输入中文或英文关键词" aria-label="全局搜索关键词" /><button class="primary" :disabled="loading || !query.trim()">{{ loading ? '搜索中…' : '搜索' }}</button></form><p v-if="error" class="error-text">{{ error }}</p><template v-if="searched && !loading"><section class="search-section"><h2>灵感（{{ ideas.length }}）</h2><div v-if="ideas.length" class="idea-list"><IdeaCard v-for="idea in ideas" :key="idea.id" :idea="idea" @changed="search" /></div><p v-else class="muted">没有匹配的灵感。</p></section><section class="search-section"><h2>商品（{{ products.length }}）</h2><div v-if="products.length" class="product-grid"><article v-for="product in products" :key="product.id" class="product-card"><div class="product-card-content"><h2><RouterLink :to="`/products/${product.id}`">{{ product.internal_name }}</RouterLink></h2><p v-if="product.final_brand_name">{{ product.final_brand_name }}</p><p v-if="product.description" class="card-summary">{{ product.description }}</p><div class="product-meta"><span v-if="product.category">{{ product.category }}</span><span class="status-badge">{{ statusLabels[product.development_status] }}</span><span>{{ product.idea_count }} 条关联灵感</span></div></div></article></div><p v-else class="muted">没有匹配的商品。</p></section></template><div v-if="!searched" class="empty-state">输入一个词，同时查找灵感和商品。</div></section></template>
